import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.DX_KL3e0.js";const m=JSON.parse('{"title":"Tạo Mã QR","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/tao-ma-qr.md","filePath":"chuc-nang/tao-ma-qr.md","lastUpdated":null}'),c={name:"chuc-nang/tao-ma-qr.md"};function e(h,n,s,l,r,g){return a(),o("div",null,[...n[0]||(n[0]=[i('<h1 id="tao-ma-qr" tabindex="-1">Tạo Mã QR <a class="header-anchor" href="#tao-ma-qr" aria-label="Permalink to &quot;Tạo Mã QR&quot;">​</a></h1><p>Biến một đường link dài thành <strong>link rút gọn + mã QR</strong> tải về được, dùng cho menu quán, wifi phòng họp, poster, tài liệu in ấn…</p><p><strong>Đường dẫn:</strong> menu <strong>Tiện ích → Tạo Mã QR</strong></p><h2 id="tao-ma-moi" tabindex="-1">Tạo mã mới <a class="header-anchor" href="#tao-ma-moi" aria-label="Permalink to &quot;Tạo mã mới&quot;">​</a></h2><ol><li><strong>Dán link</strong> cần rút gọn vào ô đầu tiên (ví dụ <code>fado.vn/tin-tuc</code>).</li><li>Đặt <strong>tên gợi nhớ</strong> để sau này tìm lại (ví dụ <em>Menu quán</em>, <em>Wifi phòng họp</em>).</li><li>Chọn <strong>thời hạn</strong>: <code>Vĩnh viễn</code>, <code>1 giờ</code>, <code>1 ngày</code>, <code>7 ngày</code>, <code>30 ngày</code>, hoặc <code>Tùy chọn…</code> để tự đặt ngày hết hạn.</li><li>Bấm tạo — hệ thống sinh link rút gọn dạng:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://assetflow.fadoai.com/s/&lt;mã&gt;</span></span></code></pre></div><p>Mã QR hiện ra ngay bên cạnh. Bấm <strong>Tải mã QR (PNG)</strong> để lấy file ảnh đem in.</p><div class="tip custom-block"><p class="custom-block-title">Vì sao QR trỏ vào link rút gọn?</p><p>Mã QR chứa link rút gọn chứ không chứa link gốc. Nhờ vậy, khi link gốc thay đổi bạn <strong>chỉ cần sửa lại đích đến</strong> — mã QR đã in ra vẫn dùng được, không phải in lại.</p></div><div class="warning custom-block"><p class="custom-block-title">Link hết hạn</p><p>Quá thời hạn đã đặt, link rút gọn ngừng hoạt động và mã QR sẽ không mở được nữa. Với poster hoặc bảng hiệu in ấn lâu dài, hãy chọn <strong>Vĩnh viễn</strong>.</p></div><h2 id="quan-ly-cac-ma-đa-tao" tabindex="-1">Quản lý các mã đã tạo <a class="header-anchor" href="#quan-ly-cac-ma-đa-tao" aria-label="Permalink to &quot;Quản lý các mã đã tạo&quot;">​</a></h2><p>Danh sách bên dưới hiển thị mọi mã bạn đã tạo, kèm mã rút gọn, link đích và thời hạn còn lại. Tại đây bạn có thể <strong>sao chép link</strong>, <strong>sửa</strong> hoặc <strong>xoá</strong> mã không dùng nữa.</p><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/giao-dien-chung.html">Giao diện chung</a> · <a href="/help/chuc-nang/kho-xuong.html">Kho / Xưởng</a></p>',13)])])}const p=t(c,[["render",e]]);export{m as __pageData,p as default};
